<?php
$yan_ligler=$pdo->query('SELECT id,lig_adi,tur FROM ligler WHERE aktif=1 ORDER BY created_at')->fetchAll();$lig_tur=$_GET['lig_tur']??'takim';if(!in_array($lig_tur,['takim','bireysel'],true))$lig_tur='takim';$grupSt=$pdo->prepare('SELECT g.id,g.grup_adi,l.lig_adi FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE l.tur=? AND l.aktif=1 ORDER BY l.lig_adi,g.grup_adi');$grupSt->execute([$lig_tur]);$gruplar=$grupSt->fetchAll();$secili=(int)($_GET['grup_id']??($gruplar[0]['id']??0));
if($lig_tur==='takim'){$st=$pdo->prepare('SELECT * FROM takimlar WHERE grup_id=? ORDER BY toplam_set DESC,toplam_puan DESC,kazanilan_mac DESC');$st->execute([$secili]);$puan=$st->fetchAll();}else{$st=$pdo->prepare('SELECT s.*,t.takim_adi FROM bireysel_lig_kayitlari k JOIN sporcular s ON s.id=k.sporcu_id LEFT JOIN takimlar t ON t.id=s.takim_id WHERE k.grup_id=? ORDER BY s.toplam_puan DESC,s.atis_sayisi ASC');$st->execute([$secili]);$puan=$st->fetchAll();}$en_iyi_takimlar=$pdo->query('SELECT id,takim_adi,toplam_set FROM takimlar ORDER BY toplam_set DESC,toplam_puan DESC LIMIT 3')->fetchAll();$en_iyi_sporcular=$pdo->query('SELECT id,ad,soyad,toplam_puan FROM sporcular WHERE atis_sayisi>0 ORDER BY toplam_puan DESC,atis_sayisi ASC LIMIT 3')->fetchAll();
?><aside class="sidebar-content"><section class="card weekly-card"><span class="eyebrow">Ligler</span><h2>Lig Merkezi</h2><?php foreach($yan_ligler as $yl):?><a class="weekly-row" href="<?= BASE_URL ?>/lig.php?id=<?= (int)$yl['id'] ?>"><b><?= $yl['tur']==='bireysel'?'🎯':'🏆' ?></b><span><?= e($yl['lig_adi']) ?></span></a><?php endforeach;?></section><section class="card standings-card"><div class="card-head"><div><span class="eyebrow">Puan durumu</span><h2>Gruplar</h2></div></div><form method="get"><label>Lig türü<select class="group-select" name="lig_tur" onchange="this.form.submit()"><option value="takim" <?= $lig_tur==='takim'?'selected':'' ?>>Takım Ligi</option><option value="bireysel" <?= $lig_tur==='bireysel'?'selected':'' ?>>Bireysel Lig</option></select></label><label>Grup<select class="group-select" name="grup_id" onchange="this.form.submit()"><?php foreach($gruplar as $g):?><option value="<?= (int)$g['id'] ?>" <?= $secili===(int)$g['id']?'selected':'' ?>><?= e($g['lig_adi'].' / '.$g['grup_adi']) ?></option><?php endforeach;?></select></label></form><div class="table-wrap"><table class="data-table compact"><thead><?php if($lig_tur==='takim'):?><tr><th>#</th><th>Takım</th><th>O</th><th>P</th></tr><?php else:?><tr><th>#</th><th>Sporcu</th><th>Puan</th></tr><?php endif;?></thead><tbody><?php foreach($puan as $i=>$x):if($lig_tur==='takim'):?><tr><td class="rank"><?= $i+1 ?></td><td><a href="<?= BASE_URL ?>/takim.php?id=<?= (int)$x['id'] ?>"><?= e($x['takim_adi']) ?></a></td><td><?= (int)$x['oynanan_mac'] ?></td><td><strong><?= (int)$x['toplam_set'] ?></strong></td></tr><?php else:?><tr><td class="rank"><?= $i+1 ?></td><td><a href="<?= BASE_URL ?>/sporcu.php?id=<?= (int)$x['id'] ?>"><?= e($x['ad'].' '.$x['soyad']) ?></a></td><td><strong><?= (int)$x['toplam_puan'] ?></strong></td></tr><?php endif;endforeach;?></tbody></table></div></section><section class="card weekly-card"><span class="eyebrow">Öne çıkanlar</span><h2>Haftanın Takımları</h2><?php foreach($en_iyi_takimlar as $i=>$t):?><a class="weekly-row" href="<?= BASE_URL ?>/takim.php?id=<?= (int)$t['id'] ?>"><b><?= $i+1 ?>.</b><span><?= e($t['takim_adi']) ?></span><em><?= (int)$t['toplam_set'] ?> set</em></a><?php endforeach;?></section><section class="card weekly-card"><h2>Haftanın Sporcuları</h2><?php foreach($en_iyi_sporcular as $i=>$s):?><a class="weekly-row" href="<?= BASE_URL ?>/sporcu.php?id=<?= (int)$s['id'] ?>"><b><?= $i+1 ?>.</b><span><?= e($s['ad'].' '.$s['soyad']) ?></span><em><?= (int)$s['toplam_puan'] ?> p.</em></a><?php endforeach;?></section></aside>
